/// <summary>
/// Controller class for Utilitas data population
/// </summary>
public final class NDXUtilitasDataOpServiceController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// canGoBatchJournal
/// </summary>
/// <returns>true</returns>
public boolean canGoBatchJournal()
{
    return true;
}

/// <summary>
/// canGoBatch
/// </summary>
/// <returns>true</returns>
public boolean canGoBatch()
{
    return true;
}

public boolean parmShowProgressForm(boolean _showProgressForm = showProgressForm)
{
    boolean ret;

    ret = super(_showProgressForm);
    ret = true;

    return ret;
}

/// <summary>
/// batch description
/// </summary>
/// <returns>NDXUtilitasData</returns>
static ClassDescription description()
{
    return 'NDXUtilitasData';
}

/// <summary>
/// Inform User after the Operation
/// </summary>
/// <param name = "_executionMode">execMode</param>
/// <param name = "_asyncResult">Result</param>
protected void afterOperation(SysOperationExecutionMode _executionMode, AifAsyncResult _asyncResult)
{
    super(_executionMode, _asyncResult);

    Info('Utilitas Import finished');
}

/// <summary>
/// Constructor
/// </summary>
/// <param name = "_className">class name</param>
/// <param name = "_methodName">method name</param>
/// <param name = "_executionMode">excution mde</param>
/// <returns>NDXUtilitasDataOpServiceController instance</returns>
public static NDXUtilitasDataOpServiceController construct(IdentifierName _className, IdentifierName _methodName, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    return new NDXUtilitasDataOpServiceController(_className, _methodName, _executionMode);
}

public static void main(Args _args)
{
    if(_args != null && _args.dataset() == tableNum(InventTable) && _args.record())
    {
        NDXUtilitasDataOpService::startPopulateBatch(_args);
    }
}
